/**
 * The app as a graph - `docs/graph.json` + `docs/ARCHITECTURE.md`.
 *
 * Read straight off the tree with regexes: no TS compiler, no hand-maintained
 * registry, so it cannot go stale in a way `bun run gen:graph` does not fix. The
 * sources are the files that already exist for another reason:
 *
 *   `.readynative.json` selection (or `modules/**` before setup)  → module nodes
 *   `src/providers.tsx` (generated by lib/generate.ts)         → provider nodes + nesting
 *   `src/lib/**`, `src/app/**`, `src/screens/**`, …            → lib/route/screen/… nodes
 *   `src/lib/env.ts` + `.readynative.json` doctor checks          → env + service nodes
 *   `from "@/…"` specifiers                                    → imports/renders edges
 *
 * Two extension points, so an agent that adds a feature can document it where it
 * wrote it: `docs/graph.extra.json` (merged verbatim) and `// @graph node=…`
 * comments in any `src/**` file.
 *
 * Output is deterministic (everything sorted, no timestamp): re-running is a no-op,
 * which is what lets `finalize` write it and CI check it with `--check`.
 */
import fs from "node:fs";
import path from "node:path";

import { readReadyNativeJson } from "./readynative-state.ts";
import { formatFile, loadPrettierOptions } from "./format.ts";

// ---------------------------------------------------------------------------
// Schema
// ---------------------------------------------------------------------------

export const NODE_KINDS = [
  "module",
  "service",
  "provider",
  "route",
  "screen",
  "feature",
  "hook",
  "store",
  "lib",
  "env",
  "script",
  "custom",
] as const;
export type NodeKind = (typeof NODE_KINDS)[number];

export const EDGE_KINDS = [
  "imports",
  "provides",
  "reads",
  "renders",
  "configures",
  "custom",
] as const;
export type EdgeKind = (typeof EDGE_KINDS)[number];

export interface GraphNode {
  id: string;
  kind: NodeKind;
  label: string;
  /** Root-relative posix path, when the node is a file. */
  file?: string;
  meta?: Record<string, unknown>;
}

export interface GraphEdge {
  from: string;
  to: string;
  kind: EdgeKind;
}

export interface Graph {
  version: 1;
  /**
   * Left unset by `buildGraph` on purpose: a timestamp in the compared content would
   * make every regeneration a diff, so `--check` (CI) and setup's
   * "second run changes nothing" would all report drift that is only the clock.
   */
  generatedAt?: string;
  nodes: GraphNode[];
  edges: GraphEdge[];
}

export const GRAPH_JSON = "docs/graph.json";
export const ARCHITECTURE_MD = "docs/ARCHITECTURE.md";
export const GRAPH_EXTRA_JSON = "docs/graph.extra.json";

/** Options a category can hold that mean "nothing was selected". */
const EMPTY_OPTIONS = new Set(["none", "off"]);

const SOURCE_EXTENSIONS = [".ts", ".tsx"];

// ---------------------------------------------------------------------------
// Filesystem helpers
// ---------------------------------------------------------------------------

function readIfExists(abs: string): string | undefined {
  return fs.existsSync(abs) ? fs.readFileSync(abs, "utf8") : undefined;
}

function isDir(abs: string): boolean {
  return fs.existsSync(abs) && fs.statSync(abs).isDirectory();
}

/** Test files are not part of the picture; `__tests__` dirs and `*.test.*` are skipped. */
function isTestPath(rel: string): boolean {
  return rel
    .split("/")
    .some((s) => s === "__tests__" || s === "__mocks__" || /\.(test|spec)\./.test(s));
}

/** Every file under `dir`, as posix paths relative to `root`, sorted. */
function walkFiles(root: string, dir: string): string[] {
  const start = path.join(root, dir);
  if (!isDir(start)) return [];
  const out: string[] = [];
  const walk = (rel: string) => {
    for (const entry of fs.readdirSync(path.join(root, rel), { withFileTypes: true })) {
      if (entry.name.startsWith(".")) continue;
      const next = `${rel}/${entry.name}`;
      if (entry.isDirectory()) walk(next);
      else out.push(next);
    }
  };
  walk(dir);
  return out.sort();
}

function listDirs(abs: string): string[] {
  if (!isDir(abs)) return [];
  return fs
    .readdirSync(abs, { withFileTypes: true })
    .filter((e) => e.isDirectory() && !e.name.startsWith("."))
    .map((e) => e.name)
    .sort();
}

/**
 * Comments out, so a docstring that mentions `process.env.EXPO_PUBLIC_X` or
 * `from "@/lib/x"` (several generated files do) does not invent a node or an edge.
 * `// @graph` annotations are read from the raw source, before this runs.
 */
function stripComments(source: string): string {
  return source.replace(/\/\*[\s\S]*?\*\//g, "").replace(/(^|[^:])\/\/[^\n]*/g, "$1");
}

function stripExtension(rel: string): string {
  return rel.replace(/\.(tsx?|jsx?|mjs|cjs)$/, "");
}

/** `revenue-cat` → `Revenue Cat`; the label a buyer recognises on a service node. */
function titleCase(id: string): string {
  return id
    .split(/[-_]/)
    .filter(Boolean)
    .map((w) => w[0].toUpperCase() + w.slice(1))
    .join(" ");
}

// ---------------------------------------------------------------------------
// Builder
// ---------------------------------------------------------------------------

class GraphBuilder {
  nodes = new Map<string, GraphNode>();
  edges: GraphEdge[] = [];

  node(node: GraphNode): void {
    // First writer wins: generated nodes are added before the extension points,
    // which are allowed to replace them (see `mergeExtra`).
    if (!this.nodes.has(node.id)) this.nodes.set(node.id, node);
  }

  put(node: GraphNode): void {
    this.nodes.set(node.id, node);
  }

  edge(from: string, to: string, kind: EdgeKind): void {
    if (from === to) return;
    this.edges.push({ from, to, kind });
  }
}

interface ModuleInfo {
  id: string;
  category: string;
  option: string;
  label: string;
  guide?: string;
  providers: { import: string; as?: string; from: string }[];
  plugins: string[];
  doctorEnvKeys: string[];
}

interface ModuleJsonShape {
  id?: string;
  label?: string;
  guide?: string;
  providers?: { import: string; as?: string; from: string }[];
  app?: { expo?: { plugins?: unknown[] } };
  doctor?: { type: string; keys?: string[] }[];
}

function readModuleJson(
  root: string,
  category: string,
  option: string
): ModuleJsonShape | undefined {
  const file = path.join(root, "modules", category, option, "module.json");
  const text = readIfExists(file);
  if (!text) return undefined;
  try {
    return JSON.parse(text) as ModuleJsonShape;
  } catch {
    return undefined;
  }
}

/** Plugin ids out of an `app.expo.plugins` array: `"expo-sqlite"` or `["expo-x", {…}]`. */
function pluginIds(plugins: unknown[] | undefined): string[] {
  if (!Array.isArray(plugins)) return [];
  const out: string[] = [];
  for (const entry of plugins) {
    if (typeof entry === "string") out.push(entry);
    else if (Array.isArray(entry) && typeof entry[0] === "string") out.push(entry[0]);
  }
  return out;
}

/**
 * The selected modules. After setup that is `.readynative.json` `selection`; before it,
 * every `modules/<category>/<option>` directory (a pre-setup tree has no selection,
 * so the graph shows the whole catalogue - which is what that tree is).
 */
function collectModules(root: string): ModuleInfo[] {
  const state = readReadyNativeJson(root);
  const pairs: [string, string][] = [];
  if (state?.selection) {
    for (const [category, option] of Object.entries(state.selection)) {
      if (!option || EMPTY_OPTIONS.has(option)) continue;
      pairs.push([category, option]);
    }
  } else {
    const modulesDir = path.join(root, "modules");
    for (const category of listDirs(modulesDir)) {
      for (const option of listDirs(path.join(modulesDir, category))) {
        if (EMPTY_OPTIONS.has(option)) continue;
        pairs.push([category, option]);
      }
    }
  }

  const doctorByModule = new Map<string, string[]>();
  // `guide` only exists post-setup (apply.ts stamps it onto the stored check); before
  // that it is read off module.json below.
  const guideByModule = new Map<string, string>();
  for (const check of state?.modules?.doctor ?? []) {
    if (check.guide) guideByModule.set(check.module, check.guide);
    if (check.type !== "env") continue;
    doctorByModule.set(check.module, [
      ...(doctorByModule.get(check.module) ?? []),
      ...(check.keys ?? []),
    ]);
  }

  return pairs
    .map(([category, option]) => {
      const json = readModuleJson(root, category, option);
      const id = json?.id ?? option;
      const fromJson = (json?.doctor ?? [])
        .filter((d) => d.type === "env")
        .flatMap((d) => d.keys ?? []);
      return {
        id,
        category,
        option,
        label: json?.label ?? option,
        guide: json?.guide ?? guideByModule.get(id),
        providers: json?.providers ?? [],
        plugins: pluginIds(json?.app?.expo?.plugins),
        doctorEnvKeys: [...new Set([...(doctorByModule.get(id) ?? []), ...fromJson])].sort(),
      };
    })
    .sort((a, b) => `${a.category}/${a.option}`.localeCompare(`${b.category}/${b.option}`));
}

// ---------------------------------------------------------------------------
// Routes
// ---------------------------------------------------------------------------

export interface RouteInfo {
  id: string;
  label: string;
  file: string;
  type: "page" | "layout" | "api";
}

/**
 * expo-router file → route. Group segments `(tabs)` do not appear in the URL,
 * `index` collapses onto its directory, `+api` files are API routes and files whose
 * name starts with `_` (other than `_layout`) are not routes at all.
 */
export function routeFromFile(rel: string): RouteInfo | undefined {
  if (!SOURCE_EXTENSIONS.includes(path.extname(rel))) return undefined;
  const inside = rel.replace(/^src\/app\/?/, "");
  const segments = stripExtension(inside).split("/");
  const name = segments[segments.length - 1];
  if (name.startsWith("_") && name !== "_layout") return undefined;
  if (name.startsWith("+") && name !== "+not-found" && !name.endsWith("+api")) return undefined;

  const dirs = segments.slice(0, -1).filter((s) => !/^\(.*\)$/.test(s));
  if (name === "_layout") {
    // Layouts of different groups share a URL, so their id keeps the real path.
    return {
      id: `route:${stripExtension(inside)}`,
      label: `${urlOf(dirs)} (layout)`,
      file: rel,
      type: "layout",
    };
  }
  const isApi = name.endsWith("+api");
  const leaf = isApi ? name.slice(0, -"+api".length) : name;
  const parts = leaf === "index" ? dirs : [...dirs, leaf];
  const url = urlOf(parts);
  return { id: `route:${url}`, label: url, file: rel, type: isApi ? "api" : "page" };
}

function urlOf(parts: string[]): string {
  return parts.length ? `/${parts.join("/")}` : "/";
}

// ---------------------------------------------------------------------------
// File → node ownership
// ---------------------------------------------------------------------------

/** Directories that become one node per file, with the `@/<dir>` specifier prefix. */
const FILE_KINDS: { dir: string; kind: NodeKind; prefix: string }[] = [
  { dir: "src/lib", kind: "lib", prefix: "lib" },
  { dir: "src/screens", kind: "screen", prefix: "screen" },
  { dir: "src/hooks", kind: "hook", prefix: "hook" },
  { dir: "src/stores", kind: "store", prefix: "store" },
];

/** The node a source file belongs to, or undefined when the file is not on the graph. */
function ownerOf(rel: string): string | undefined {
  if (isTestPath(rel)) return undefined;
  if (rel.startsWith("src/app/")) return routeFromFile(rel)?.id;
  if (rel.startsWith("src/features/")) {
    const name = rel.slice("src/features/".length).split("/")[0];
    return name ? `feature:${name}` : undefined;
  }
  for (const { dir, prefix } of FILE_KINDS) {
    if (!rel.startsWith(`${dir}/`)) continue;
    if (!SOURCE_EXTENSIONS.includes(path.extname(rel))) return undefined;
    return `${prefix}:${stripExtension(rel.slice(dir.length + 1))}`;
  }
  if (/^scripts\/[^/]+\.ts$/.test(rel)) return `script:${stripExtension(path.basename(rel))}`;
  return undefined;
}

/**
 * `@/…` specifier → node id. `@/components/ui` and `@/components/**` are deliberately not on the
 * graph: every screen imports the primitive kit, and an edge from all of them to one
 * node says nothing.
 */
function nodeForSpecifier(spec: string, nodes: Map<string, GraphNode>): string | undefined {
  const rest = spec.slice(2);
  const candidates: string[] = [];
  for (const { dir, prefix } of FILE_KINDS) {
    const short = dir.slice("src/".length);
    if (rest === short || rest.startsWith(`${short}/`)) {
      const name = rest.slice(short.length + 1);
      candidates.push(`${prefix}:${name}`, `${prefix}:${name}/index`);
    }
  }
  if (rest.startsWith("features/"))
    candidates.push(`feature:${rest.slice("features/".length).split("/")[0]}`);
  return candidates.find((id) => nodes.has(id));
}

// ---------------------------------------------------------------------------
// Providers
// ---------------------------------------------------------------------------

const IMPORT_RE = /import\s+(?:type\s+)?\{([^}]*)\}\s+from\s+["']([^"']+)["']/g;
const SPECIFIER_RE = /from\s+["'](@\/[^"']+)["']/g;
const JSX_OPEN_RE = /<([A-Z][A-Za-z0-9_]*)\b/g;
const ENV_MEMBER_RE = /\benv\.([A-Z][A-Z0-9_]*)\b/g;
const PROCESS_ENV_RE = /\bprocess\.env\.([A-Z][A-Z0-9_]*)\b/g;
const PUBLIC_ENV_RE = /EXPO_PUBLIC_[A-Z0-9_]+/g;
const GRAPH_COMMENT_RE = /\/\/\s*@graph\s+([^\n]*)/g;

export interface ProviderInfo {
  name: string;
  from: string;
  order: number;
}

/**
 * `src/providers.tsx` is generated (lib/generate.ts): one import line per source and a
 * single nested JSX tree. The JSX is the order that matters, so it - not the import
 * list - is what is read here.
 */
export function parseProviders(source: string): ProviderInfo[] {
  const sourceOf = new Map<string, string>();
  for (const [, specifiers, from] of source.matchAll(IMPORT_RE)) {
    for (const raw of specifiers.split(",")) {
      const parts = raw.trim().split(/\s+as\s+/);
      const local = (parts[1] ?? parts[0]).trim();
      if (local) sourceOf.set(local, from);
    }
  }
  const body = source.slice(source.indexOf("return ("));
  const seen = new Set<string>();
  const out: ProviderInfo[] = [];
  for (const [, name] of body.matchAll(JSX_OPEN_RE)) {
    if (seen.has(name) || !sourceOf.has(name)) continue;
    seen.add(name);
    out.push({ name, from: sourceOf.get(name) as string, order: out.length });
  }
  return out;
}

/** `QueryProvider` → `query`: what a provider is matched against when modules/ is gone. */
function providerStem(name: string): string {
  return name.replace(/Provider$|Host$/, "").toLowerCase();
}

function moduleForProvider(provider: ProviderInfo, modules: ModuleInfo[]): ModuleInfo | undefined {
  const owner = modules.find((m) => m.providers.some((p) => (p.as ?? p.import) === provider.name));
  if (owner) return owner;
  const stem = providerStem(provider.name);
  if (!stem) return undefined;
  return modules.find(
    (m) =>
      m.category === stem ||
      m.option === stem ||
      m.option.includes(stem) ||
      stem.includes(m.option) ||
      m.id === stem
  );
}

// ---------------------------------------------------------------------------
// `// @graph` annotations
// ---------------------------------------------------------------------------

export interface Annotation {
  node: GraphNode;
  edges: string[];
}

/** `// @graph node=<id> kind=<kind> label="…" [edges=<id>,<id>]` - one node per line. */
export function parseAnnotations(source: string, file: string): Annotation[] {
  const out: Annotation[] = [];
  for (const [, rest] of source.matchAll(GRAPH_COMMENT_RE)) {
    const fields = new Map<string, string>();
    for (const [, key, quoted, bare] of rest.matchAll(/(\w+)=(?:"([^"]*)"|(\S+))/g)) {
      fields.set(key, quoted ?? bare ?? "");
    }
    const id = fields.get("node");
    if (!id) continue;
    const kind = fields.get("kind") as NodeKind | undefined;
    out.push({
      node: {
        id,
        kind: kind && (NODE_KINDS as readonly string[]).includes(kind) ? kind : "custom",
        label: fields.get("label") ?? id,
        file,
      },
      edges: (fields.get("edges") ?? "")
        .split(",")
        .map((s) => s.trim())
        .filter(Boolean),
    });
  }
  return out;
}

// ---------------------------------------------------------------------------
// buildGraph
// ---------------------------------------------------------------------------

const KIND_ORDER = new Map(NODE_KINDS.map((k, i) => [k, i]));

function sortGraph(nodes: GraphNode[], edges: GraphEdge[]): Graph {
  const seen = new Set<string>();
  const uniqueEdges = edges.filter((e) => {
    const key = `${e.from}|${e.kind}|${e.to}`;
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });
  return {
    version: 1,
    nodes: [...nodes].sort(
      (a, b) =>
        (KIND_ORDER.get(a.kind) ?? 99) - (KIND_ORDER.get(b.kind) ?? 99) || a.id.localeCompare(b.id)
    ),
    edges: uniqueEdges.sort(
      (a, b) =>
        a.from.localeCompare(b.from) || a.kind.localeCompare(b.kind) || a.to.localeCompare(b.to)
    ),
  };
}

function mergeExtra(root: string, b: GraphBuilder): void {
  const text = readIfExists(path.join(root, GRAPH_EXTRA_JSON));
  if (!text) return;
  let extra: { nodes?: GraphNode[]; edges?: GraphEdge[] };
  try {
    extra = JSON.parse(text) as { nodes?: GraphNode[]; edges?: GraphEdge[] };
  } catch {
    // Unreadable extras must not take the whole graph down; `validateGraph` has no
    // way to say it, so the file is simply ignored (gen-graph prints the parse error).
    return;
  }
  for (const node of extra.nodes ?? []) if (node?.id) b.put(node);
  for (const edge of extra.edges ?? []) if (edge?.from && edge?.to) b.edges.push(edge);
}

export function buildGraph(root: string): Graph {
  const b = new GraphBuilder();
  const modules = collectModules(root);

  // 1. Modules, the services they need and the app plugins they configure.
  for (const m of modules) {
    const id = `module:${m.category}/${m.option}`;
    b.node({
      id,
      kind: "module",
      label: `${m.category}: ${m.label}`,
      file: isDir(path.join(root, "modules", m.category, m.option))
        ? `modules/${m.category}/${m.option}`
        : undefined,
      meta: { category: m.category, option: m.option, ...(m.guide ? { guide: m.guide } : {}) },
    });
    for (const plugin of m.plugins) {
      b.node({ id: `plugin:${plugin}`, kind: "custom", label: `${plugin} (app plugin)` });
      b.edge(id, `plugin:${plugin}`, "configures");
    }
    if (m.doctorEnvKeys.length) {
      const service = `service:${m.id}`;
      b.node({
        id: service,
        kind: "service",
        label: titleCase(m.id),
        meta: { env: m.doctorEnvKeys, ...(m.guide ? { guide: m.guide } : {}) },
      });
      b.edge(id, service, "configures");
    }
  }

  // 2. env keys: what `src/lib/env.ts` exposes, plus the server-only keys that only
  //    doctor knows about (they never reach the client schema).
  const envSource = stripComments(readIfExists(path.join(root, "src/lib/env.ts")) ?? "");
  const envKeys = new Set<string>(envSource.match(PUBLIC_ENV_RE) ?? []);
  for (const m of modules) for (const key of m.doctorEnvKeys) envKeys.add(key);
  for (const key of [...envKeys].sort()) {
    b.node({ id: `env:${key}`, kind: "env", label: key });
  }
  for (const m of modules) {
    for (const key of m.doctorEnvKeys) b.edge(`service:${m.id}`, `env:${key}`, "reads");
  }

  // 3. File nodes.
  for (const rel of walkFiles(root, "src/app")) {
    const route = routeFromFile(rel);
    if (!route || isTestPath(rel)) continue;
    b.node({
      id: route.id,
      kind: "route",
      label: route.label,
      file: rel,
      meta: { type: route.type },
    });
  }
  for (const { dir, kind, prefix } of FILE_KINDS) {
    for (const rel of walkFiles(root, dir)) {
      if (isTestPath(rel) || !SOURCE_EXTENSIONS.includes(path.extname(rel))) continue;
      const name = stripExtension(rel.slice(dir.length + 1));
      b.node({ id: `${prefix}:${name}`, kind, label: `@/${dir.slice(4)}/${name}`, file: rel });
    }
  }
  for (const name of listDirs(path.join(root, "src/features"))) {
    b.node({
      id: `feature:${name}`,
      kind: "feature",
      label: `@/features/${name}`,
      file: `src/features/${name}`,
    });
  }
  for (const rel of walkFiles(root, "scripts")) {
    const owner = ownerOf(rel);
    if (!owner) continue;
    b.node({
      id: owner,
      kind: "script",
      label: `scripts/${path.basename(rel)}`,
      file: rel,
    });
  }

  // 4. Providers: the composition order of `src/providers.tsx`, outer first.
  const providersSource = readIfExists(path.join(root, "src/providers.tsx")) ?? "";
  const providers = parseProviders(stripComments(providersSource));
  for (const p of providers) {
    b.node({
      id: `provider:${p.name}`,
      kind: "provider",
      label: p.name,
      file: providersSource ? "src/providers.tsx" : undefined,
      meta: { from: p.from, order: p.order },
    });
  }
  for (let i = 0; i < providers.length - 1; i++) {
    // Outer provider renders the next one in: that nesting is the app's boot order.
    b.edge(`provider:${providers[i].name}`, `provider:${providers[i + 1].name}`, "renders");
  }
  for (const p of providers) {
    const owner = moduleForProvider(p, modules);
    if (owner) b.edge(`module:${owner.category}/${owner.option}`, `provider:${p.name}`, "provides");
    const target = p.from.startsWith("@/") ? nodeForSpecifier(p.from, b.nodes) : undefined;
    if (target) b.edge(`provider:${p.name}`, target, "imports");
  }

  // 5. Edges read out of the sources themselves.
  const sourceFiles = [
    ...walkFiles(root, "src"),
    ...walkFiles(root, "scripts").filter((rel) => /^scripts\/[^/]+\.ts$/.test(rel)),
  ];
  const annotations: Annotation[] = [];
  for (const rel of sourceFiles) {
    if (!SOURCE_EXTENSIONS.includes(path.extname(rel))) continue;
    const raw = readIfExists(path.join(root, rel));
    if (raw === undefined) continue;
    if (!isTestPath(rel)) annotations.push(...parseAnnotations(raw, rel));

    const owner = ownerOf(rel);
    if (!owner || !b.nodes.has(owner)) continue;
    const source = stripComments(raw);

    for (const [, spec] of source.matchAll(SPECIFIER_RE)) {
      const target = nodeForSpecifier(spec, b.nodes);
      if (!target) continue;
      const renders = owner.startsWith("route:") && target.startsWith("screen:");
      b.edge(owner, target, renders ? "renders" : "imports");
    }
    for (const re of [ENV_MEMBER_RE, PROCESS_ENV_RE]) {
      for (const [, key] of source.matchAll(re)) {
        const id = [`env:EXPO_PUBLIC_${key}`, `env:${key}`].find((c) => b.nodes.has(c));
        if (id) b.edge(owner, id, "reads");
      }
    }
  }

  // 6. Extension points. Annotations first so `docs/graph.extra.json` has the last word.
  for (const { node, edges } of annotations) {
    b.put(node);
    for (const to of edges) b.edge(node.id, to, "custom");
  }
  mergeExtra(root, b);

  return sortGraph([...b.nodes.values()], b.edges);
}

/** Dangling endpoints are warnings, never errors: an extra edge may point at future work. */
export function validateGraph(graph: Graph): string[] {
  const ids = new Set(graph.nodes.map((n) => n.id));
  const warnings: string[] = [];
  for (const e of graph.edges) {
    for (const end of [e.from, e.to]) {
      if (!ids.has(end)) warnings.push(`edge ${e.from} -${e.kind}-> ${e.to}: no node "${end}"`);
    }
  }
  return [...new Set(warnings)].sort();
}

// ---------------------------------------------------------------------------
// Rendering
// ---------------------------------------------------------------------------

function mermaidId(id: string): string {
  return `n${id.replace(/[^A-Za-z0-9]/g, "_")}`;
}

function mermaidLabel(label: string): string {
  return label.replace(/"/g, "#quot;");
}

export function renderMermaid(graph: Graph): string {
  const lines = ["flowchart LR"];
  for (const kind of NODE_KINDS) {
    const nodes = graph.nodes.filter((n) => n.kind === kind);
    if (!nodes.length) continue;
    lines.push(`  subgraph ${kind}s["${kind}"]`);
    for (const n of nodes) lines.push(`    ${mermaidId(n.id)}["${mermaidLabel(n.label)}"]`);
    lines.push("  end");
  }
  const ids = new Set(graph.nodes.map((n) => n.id));
  for (const e of graph.edges) {
    if (!ids.has(e.from) || !ids.has(e.to)) continue;
    lines.push(`  ${mermaidId(e.from)} -->|${e.kind}| ${mermaidId(e.to)}`);
  }
  return lines.join("\n");
}

const START_HERE = `\`bun run setup\` picked the stack and wrote it down in \`.readynative.json\`; the providers it
composed are in \`src/providers.tsx\`, the env keys it needs in \`src/lib/env.ts\` (\`bun run doctor\`
tells you which ones are still missing). Every category has a shim in \`@/lib/<category>\` that
exists whether or not a module is selected, so screens import \`@/lib/auth\` and never a vendor
SDK. Screen bodies live in \`src/screens\`, \`src/app\` only routes to them.`;

function table(nodes: GraphNode[]): string {
  const rows = nodes.map((n) => `| \`${n.id}\` | ${n.label} | ${n.file ? `\`${n.file}\`` : "-"} |`);
  return ["| id | label | file |", "| --- | --- | --- |", ...rows].join("\n");
}

export function renderArchitecture(graph: Graph): string {
  const parts = [
    "# Architecture",
    "",
    "Generated by `bun run gen:graph` - do not edit; add nodes via docs/graph.extra.json or `// @graph` comments.",
    "",
    "## Start here",
    "",
    START_HERE,
    "",
    "## Map",
    "",
    "```mermaid",
    renderMermaid(graph),
    "```",
    "",
  ];
  for (const kind of NODE_KINDS) {
    const nodes = graph.nodes.filter((n) => n.kind === kind);
    if (!nodes.length) continue;
    parts.push(`## ${kind} (${nodes.length})`, "", table(nodes), "");
  }
  return `${parts.join("\n").trimEnd()}\n`;
}

// ---------------------------------------------------------------------------
// Files
// ---------------------------------------------------------------------------

export interface GraphFile {
  rel: string;
  content: string;
}

/** The two artefacts, prettier-formatted (`prettier --check` / a format run would reformat them otherwise). */
export async function graphFiles(root: string, graph = buildGraph(root)): Promise<GraphFile[]> {
  const options = loadPrettierOptions(root);
  return [
    {
      rel: GRAPH_JSON,
      content: await formatFile(GRAPH_JSON, JSON.stringify(graph, null, 2), options),
    },
    {
      rel: ARCHITECTURE_MD,
      content: await formatFile(ARCHITECTURE_MD, renderArchitecture(graph), options),
    },
  ];
}

/**
 * Writes both files. `write` is injectable so a caller with its own reporting writer
 * (setup's, which reports written/unchanged) can route them through it; the default
 * writes only when the bytes change, so a re-run leaves the tree - and git - alone.
 */
export async function writeGraph(
  root: string,
  write?: (rel: string, content: string) => void
): Promise<string[]> {
  const written: string[] = [];
  for (const { rel, content } of await graphFiles(root)) {
    if (write) {
      write(rel, content);
      written.push(rel);
      continue;
    }
    const abs = path.join(root, rel);
    if (readIfExists(abs) === content) continue;
    fs.mkdirSync(path.dirname(abs), { recursive: true });
    fs.writeFileSync(abs, content);
    written.push(rel);
  }
  return written;
}

/** `--check`: the files that differ from a fresh build (CI fails on a non-empty list). */
export async function checkGraph(root: string): Promise<string[]> {
  const drift: string[] = [];
  for (const { rel, content } of await graphFiles(root)) {
    if (readIfExists(path.join(root, rel)) !== content) drift.push(rel);
  }
  return drift;
}
